pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 _feeRate) public {
        // Restrict to values that make the check fail (above 5000) so the call reverts.
        vm.assume(_feeRate > 5000);

        // Call initialize; it should revert because of the fee rate check.
        // We just need the execution to happen; we know it will revert.
        // The property: after a reverting call, `feeRate` must still be its initial value (0).
        try c.initialize(
            address(0x1),
            address(0x2),
            1,
            1,
            1,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            // Should not succeed for _feeRate > 5000;
            // if it does, the test should still observe the difference (but it won't).
        } catch { }

        // After the reverting transaction, the correct contract leaves feeRate unchanged (0),
        // but the mutant has already written the high _feeRate into storage.
        assertEq(c.feeRate(), 0, "feeRate should remain 0 after a reverting initialize due to high fee");
    }
}
